def __repr__(self):

    args = [
        f'tables={list(self.tables())}',
        f'tables_count={len(self.tables())}',
        f'default_table_documents_count={self.__len__()}',
        f'all_tables_documents_count={[f"{table}={len(self.table(table))}" for table in self.tables()]}',
